    for i in range(2, sqrt_n + 1):
        if n % i == 0:
            return False
    return True


def is_prime_b(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    for i in range(2, int(n // 2) + 1):
        if n % i == 0:
            return False
    return True


def is_prime_c(n):
    divisible = 0
    for i in range(1, n + 1):
        if n % i == 0:
            divisible += 1
    if divisible == 2:
        return True
    return False

